const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const la_point = ee.Geometry.Point([-118.2436826460509, 33.97811334086217]);
  const sd_point = ee.Geometry.Point([-117.15380986802357, 32.7358717958782]);
  const start_date = '2018-01-01';
  const end_date = '2019-12-31';

  // 2. Data Acquisition
  const no2_col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('NO2_column_number_density')
    .filterDate(start_date, end_date);

  const la_col = no2_col.filterBounds(la_point);
  const sd_col = no2_col.filterBounds(sd_point);

  const la_size = la_col.size().getInfo();
  const sd_size = sd_col.size().getInfo();

  console.log(`LA images: ${la_size}, SD images: ${sd_size}`);

  if (la_size === 0 || sd_size === 0) {
    console.log('No data for one or both locations.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Quality Masking Function
  function maskNO2(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  const la_masked = la_col.map(maskNO2);
  const sd_masked = sd_col.map(maskNO2);

  // 4. Calculate mean NO2
  const la_mean_img = la_masked.mean();
  const sd_mean_img = sd_masked.mean();

  // Check pixel counts
  const la_count = la_mean_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: la_point.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const sd_count = sd_mean_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sd_point.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  console.log(`LA valid pixels: ${la_count}, SD valid pixels: ${sd_count}`);

  if (la_count === 0 || sd_count === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Get mean values
  const la_no2 = la_mean_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: la_point.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const sd_no2 = sd_mean_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sd_point.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  console.log(`LA NO2: ${la_no2}, SD NO2: ${sd_no2}`);

  // 5. Validation & Final Answer
  if (la_no2 === null || sd_no2 === null || isNaN(la_no2) || isNaN(sd_no2)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`LA avg NO2: ${la_no2.toExponential(3)}, SD avg NO2: ${sd_no2.toExponential(3)}`);

  if (la_no2 > sd_no2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
